// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // set up a non-owner caller
        address player = address(0x123);
        vm.deal(player, 1 ether);
        vm.prank(player);
        // try to wager with value 0 (betLimit is 0)
        (bool ok, ) = address(c).call{value: 0}(abi.encodeWithSignature("wager()"));
        // Reference: reverts because openToPublic is false => require(openToPublic) fails => ok == false
        // Buggy: does not revert because require(!openToPublic) passes => ok == true
        assertTrue(ok);
    }
}

