contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // The constructor is called in setUp(). In the reference version it succeeds,
        // so after setUp(), c is deployed. In the second version it reverts, so setUp()
        // would revert and the test would fail before reaching this function.
        // To catch the revert, we call the constructor again via try/catch.
        bool ok;
        try new C(address(this), 0) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

