// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Set up: open the contract, adjust difficulty to 1
        vm.prank(address(this));
        c.OpenToThePublic();
        vm.prank(address(this));
        c.AdjustDifficulty(1);

        // play() with no wager should revert because wagers[msg.sender] == 0
        // In the reference, difficulty is 1; in buggy, difficulty is 0 (set to 0 in AdjustDifficulty)
        // The onlyPlayers modifier checks wagers[msg.sender] > 0, so it reverts anyway.
        // To observe the divergence, we need a player who has wagered.
        // Give the player ether and let them wager
        address player = address(0x1234);
        vm.deal(player, 1 ether);
        vm.prank(player);
        c.wager{value: 0}(); // betLimit is 0, so msg.value == 0 works

        // Now try play() - it will revert in the reference because difficulty=1 leads to
        // winningNumber = keccak256(...) % 1 + 1 = 1, and difficulty/2 = 0, so condition false,
        // then loseWager(betLimit/2) called. In buggy version, difficulty=0 -> modulo 0 causes revert.
        // So the reference succeeds (doesn't revert), buggy reverts.
        vm.prank(player);
        bool ok;
        try c.play() { ok = true; } catch { ok = false; }
        // Reference: play() succeeds (ok=true). Buggy: play() reverts (ok=false).
        assertTrue(ok);
    }
}

