pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testRegression_property() public {
        // Set up: open to public, adjust bet limit, set difficulty to 5, then have player wager
        c.OpenToThePublic();
        c.AdjustBetAmounts(1 ether);
        c.AdjustDifficulty(5);
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        c.wager{value: 1 ether}();
        // Now adjust difficulty to 0 — reference sets difficulty = 0, bug sets difficulty = 0 anyway
        c.AdjustDifficulty(0);
        // Attempt play() — in reference, difficulty is 0, winningNumber % 0 reverts; but the bug also does that.
        // Actually the bug always sets difficulty = 0 regardless of argument, so after AdjustDifficulty(0) both are 0.
        // We need a different angle: after calling AdjustDifficulty(5) in setup, the bug overrides to 0.
        // So after setup, reference difficulty = 5, bug difficulty = 0.
