        // Fund contract with 10 ether
        vm.deal(address(this), 10 ether);
        payable(address(c)).transfer(10 ether);

        uint256 bet = 1 ether;
        vm.prank(address(this));
        c.AdjustBetAmounts(bet);

        address player = address(0x1234);
        vm.deal(player, bet);
        vm.prank(player);
        c.wager{value: bet}();

        vm.roll(block.number + 1);

        uint256 balanceBeforePlay = address(c).balance;
        vm.prank(player);
        c.play();
        uint256 balanceAfterPlay = address(c).balance;

        // In reference (difficulty=1): winningNumber=1 !=0, so loseWager(bet/2). Contract loses bet/2 = 0.5 ether.
        // Balance decreases by 0.5 ether. So balanceAfterPlay == balanceBeforePlay - bet/2.
        // In buggy inversion: winningNumber !=0 so payout(half balance). Balance decreases by half (5 ether).
        // So reference passes, buggy fails.
        assertEq(balanceAfterPlay, balanceBeforePlay - bet / 2);
    }
}

